# Sarel sculpted from nothing on the skeleton and clips of the game's own export of it (sculptkit.py):
#   blender --background --factory-startup --python sculpts/sarel.py -- <the export's Sarel.glb> <out.glb>
#
# Carpathia No. 10133, the Salt Pokemon (plan 46, CP-dex-3, "133. Sarel: a salt crystal"); no sculptor in the game, so
# its export is a body generated by rule (a root and a body bone): only its skeleton, its clips and its size are taken.
# From the picture: a cube of rock salt built of blocks with cut edges, cloudy white mottled with pale pink: four
# slabs on its top, a great block across its front that is its face, a column of blocks down its right side and a row
# of blocks along its bottom, with dark cracks between; four short crystal feet, tapering, under its corners; a sleepy
# face low on the front block: two half-shut eyes under heavy lids, a tiny pink nose. The salt grains falling round
# it in the picture are a drawn effect and are left out.
#
# Written to be grown from (salinax.py imports it with sibling): the line's colours, the cut block, the crystal, the
# mottle and the sleepy eye are here; the build is under the main guard.
import os, sys, math
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import numpy as np
from mathutils import Euler
from sculptkit import Kit, ell, srgb, unit, eye_look, args, hull, slab, polygon, inside, boxy, axes

# --- the line's colours -----------------------------------------------------------------------------------------------
SALT, PINKSALT, ROSE = "#F4EFEF", "#EFD5D4", "#E5BDBB"     # white salt, pale pink salt, its deeper pink
CRACK, FOOT = "#A88888", "#E8DCDC"                          # the cracks between blocks, the crystal feet
NOSE, IRIS, INK, WHITE = "#E39C9A", "#4A2E28", "#2E1C1A", "#FBF8F6"


# --- shapes ----------------------------------------------------------------------------------------------------------
def block(lo, hi, rot=(0, 0, 0), cham=0.3):
    """A block of salt from its low corner to its high one, its edges and corners cut back (a hull, hard edges)."""
    lo, hi = np.array(lo, float), np.array(hi, float)
    c, h = (lo + hi) / 2, (hi - lo) / 2
    e = cham * min(h)
    pts = []
    for sx in (-1, 1):
        for sy in (-1, 1):
            for sz in (-1, 1):
                s = np.array([sx, sy, sz], float)
                for k in range(3):
                    q = s * h
                    q[k] -= s[k] * e
                    pts.append(q)
    P = np.array(pts)
    m = np.array(Euler([math.radians(a) for a in rot]).to_matrix())
    return hull(P @ m.T + c)


def crystal(top, bottom, r_top, r_bot, n=6, twist=0.0):
    """A tapering crystal from its top to its blunt point: a prism of n faces narrowing to a smaller face."""
    top, bottom = np.array(top, float), np.array(bottom, float)
    a, b = axes(bottom - top)
    pts = []
    for i in range(n):
        t = 2 * math.pi * i / n + twist
        pts.append(top + r_top * (math.cos(t) * a + math.sin(t) * b))
        pts.append(bottom + r_bot * (math.cos(t + 0.3) * a + math.sin(t + 0.3) * b))
    return hull(pts)


def mottle(seed=0.0, amount=1.25, scale=1.0):
    """Clouds of pink through white salt: 0..1 by a sum of waves (a paint mask)."""
    def m(P):
        x, y, z = P[:, 0] * scale, P[:, 1] * scale, P[:, 2] * scale
        w = (np.sin(x * 21 + seed) + np.sin(z * 17 + x * 7 + 2 * seed) + np.sin(y * 19 - z * 5 + 3 * seed)
             + 0.3 * np.sin(x * 13 - y * 11 + z * 9))
        return inside(amount - w, 0.12)
    return m


# --- the sleepy eye: a heavy lid over its top, a dark eye under it with a glint, a white rim below -------------------
LID_LINE = 0.18


def sleepy_open(white=WHITE, iris=IRIS, ink=INK, lid=SALT, line=LID_LINE):
    CW, CI, CK, CL = srgb(white), srgb(iris), srgb(ink), srgb(lid)

    def look(u, v):
        c = np.tile(CW, (len(u), 1))
        c[((u + 0.05) / 0.62) ** 2 + ((v + 0.12) / 0.7) ** 2 < 1] = CI
        c[((u - 0.12) / 0.15) ** 2 + ((v - 0.0) / 0.13) ** 2 < 1] = CW
        top = line - 0.12 * u * u
        c[v > top] = CL
        c[np.abs(v - top) < 0.15] = CK
        c[(u * u + v * v > 0.8) & (v <= top)] = CK
        return c
    return look


def lay_sleepy(k, centre, normal, half, lid, look=None, mirror_x=True):
    look = look or sleepy_open(lid=lid)
    def lay(state):
        f = look if state == "Open" else eye_look(state, look, srgb(lid), srgb(INK), line=0.2)
        k.decal(centre, normal, half, f, eps=0.0025, rings=20, segs=56, mirror=mirror_x)
    return lay


# --- Sarel ------------------------------------------------------------------------------------------------------------
FRONT = -0.385
EYE_X, EYE_Z, EYE_HALF = 0.11, 0.455, (0.06, 0.047)
G = 0.008          # the crack between blocks


def blocks(k):
    B = [  # low corner, high corner, colour, turn
        # the bottom row
        ((-0.34, -0.33, 0.115), (-0.04 - G, -0.01, 0.335), PINKSALT, (0, 0, 2)),
        ((-0.04, -0.34, 0.11), (0.335, -0.01, 0.33), SALT, (0, 0, -2)),
        ((-0.33, 0.0 + G, 0.115), (0.0, 0.33, 0.335), SALT, (0, 0, 1)),
        ((0.0 + G, 0.0 + G, 0.11), (0.335, 0.335, 0.33), ROSE, (0, 0, -1)),
        # the middle: the column down the right side, the two at the back
        ((0.262 + G, -0.33, 0.335 + G), (0.355, 0.02, 0.68), PINKSALT, (0, 0, 0)),
        ((-0.345, 0.01, 0.335 + G), (-0.01, 0.34, 0.672), PINKSALT, (0, 0, -1)),
        ((0.0, 0.04, 0.335 + G), (0.35, 0.34, 0.672), SALT, (0, 0, 1)),
        # the four slabs on the top
        ((-0.355, -0.345, 0.672 + G), (-0.03, -0.02, 0.83), SALT, (1, -2, 0)),
        ((-0.02, -0.36, 0.672 + G), (0.34, -0.03, 0.85), PINKSALT, (-1, 1, -2)),
        ((-0.345, -0.01, 0.672 + G), (-0.01, 0.34, 0.835), PINKSALT, (0, 1, 2)),
        ((0.0, 0.0, 0.672 + G), (0.35, 0.345, 0.842), ROSE, (1, 0, -1)),
    ]
    for i, (lo, hi, col, rot) in enumerate(B):
        k.add(f"block{i}", block(lo, hi, rot), col, "body", fuse=False, surface="shell")


def face_block(k):
    """The great block across the front, fused (its face carries the eyes): a rounded box, clouded with pink."""
    c, h = np.array([-0.04, -0.225, 0.505]), np.array([0.302, 0.16, 0.17])
    k.add("face", ell(c, h, deform=boxy(4.5)), SALT, "body")
    # the core that fills the cube behind it, dark between the blocks
    k.add("core", ell((0.0, 0.02, 0.48), (0.31, 0.3, 0.35), deform=boxy(7)), CRACK, "body")
    k.paint(mottle(0.4, 1.15), PINKSALT, on=["face"])
    k.paint(mottle(2.1, 1.9, 1.3), ROSE, on=["face"])
    # clear the face round the eyes and the nose
    k.paint(lambda P: inside(np.hypot((np.abs(P[:, 0]) - EYE_X) / 1.3, P[:, 2] - EYE_Z) - 0.065, 0.01)
            * inside(P[:, 1] + 0.3, 0.01), SALT, on=["face"])
    k.decal((-0.01, FRONT, 0.378), (0, -1, 0), (0.022, 0.014), NOSE, eps=0.0025, rings=8, segs=36,
            outline=polygon([(-1, 0.6), (1, 0.6), (0.0, -1.0)]))
    k.decal((EYE_X + 0.03, FRONT, 0.375), (0, -1, 0), (0.035, 0.016), PINKSALT, eps=0.002, rings=6, segs=32)


def feet(k):
    for i, (x, y) in enumerate(((-0.2, -0.2), (0.19, -0.22), (-0.2, 0.2), (0.21, 0.19))):
        k.add(f"foot{i}", crystal((x, y, 0.15), (x * 1.05, y * 1.05, 0.006), 0.075, 0.042, twist=0.3 * i), FOOT, "body",
              fuse=False, surface="shell")


def sarel(src, out):
    k = Kit(src, coat="shell")
    blocks(k)
    face_block(k)
    feet(k)
    k.build(voxel=0.0072, smooth=3, band=0.005)
    k.eye_states(lay_sleepy(k, (EYE_X, FRONT, EYE_Z), (0, -1, 0), EYE_HALF, SALT))
    k.export(out)


if __name__ == "__main__":
    sarel(*args())
